async function loadStorage(level) {
  try {
    const raw = localStorage.getItem(`ru_${level.toLowerCase()}_progress`);
    if (raw) {
      const data = JSON.parse(raw);
      return { badList: data.badList || [], mastery: data.mastery || {} };
    }
  } catch {}
  return { badList: [], mastery: {} };
}
async function saveStorage(level, badList, mastery) {
  try {
    localStorage.setItem(`ru_${level.toLowerCase()}_progress`, JSON.stringify({ badList, mastery }));
  } catch {}
}

