function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function getWrongChoices(words, correct, n = 3) {
  const others = words.filter(w => w.ru !== correct.ru);
  return shuffle(others).slice(0, n);
}

// Adjective endings are stored as full inflected forms (e.g. "новая", "новое", "новые").
// For regular adjectives, show just the part that differs from the base word, e.g.
// "новый -ая -ое -ые", instead of repeating the whole word for each gender. Comparison
// strips combining stress marks first so a shifted accent (e.g. сам -> сама́, where the
// stress jumps to a later syllable) doesn't create a false mismatch and cut the shared
// stem short. Genuinely irregular/suppletive words (весь -> вся, тот -> та, чей -> чья)
// don't share enough of the base word for a "-ending" reading to make sense, so those
// return null and the caller falls back to showing the full forms.
function stripAccent(s) {
  return s.replace(/́/g, "");
}
function commonPrefixLenStripped(a, b) {
  const as = stripAccent(a), bs = stripAccent(b);
  const len = Math.min(as.length, bs.length);
  let i = 0;
  while (i < len && as[i] === bs[i]) i++;
  return i;
}
function origIndexForStrippedIndex(orig, strippedIdx) {
  let count = 0;
  for (let i = 0; i < orig.length; i++) {
    if (orig[i] === "́") continue;
    if (count === strippedIdx) return i;
    count++;
  }
  return orig.length;
}
function formatAdjEndings(base, endings) {
  if (!base || !endings || endings.length === 0) return null;
  const baseLen = stripAccent(base).length;
  if (baseLen === 0) return null;
  const minCut = Math.min(...endings.map(e => commonPrefixLenStripped(base, e)));
  if (minCut / baseLen < 0.45) return null;
  return endings.map(e => `-${e.slice(origIndexForStrippedIndex(e, minCut))}`);
}

// Matching for typed answers WITHOUT stress: normalize case, strip punctuation
function normalizeNoStress(s) {
  return s.trim().toLowerCase().replace(/ё/g, "е").replace(/\s+/g, " ");
}

// Matching for typed answers WITH stress: user types CAPS on the stressed vowel.
// We compare against the ruTyping field which already encodes stress the same way.
function normalizeWithStress(s) {
  return s.trim().replace(/\s+/g, " ");
}

function normalizeEn(s) {
  return s.trim().toLowerCase().replace(/[^a-z\s]/g, "").replace(/\s+/g, " ").trim();
}

const TOTAL = 20;

function AbbrevChip({ token, chipId }) {
  const { expandedId, setExpandedId } = useChipState();
  const info = ABBREV_GLOSSARY[token];
  const shown = expandedId === chipId;
  if (!info) return <span>{token}</span>;
  return (
    <span
      className={`abbrev-chip-block${shown ? " expanded" : ""}`}
      onClick={() => setExpandedId(shown ? null : chipId)}
    >
      <span className={`abbrev-chip-token${shown ? " token-active" : ""}`}>{token}</span>
    </span>
  );
}

function AbbrevText({ text }) {
  const tokens = Object.keys(ABBREV_GLOSSARY).sort((a, b) => b.length - a.length);
  const pattern = new RegExp(`(${tokens.map(t => t.replace(/[.$*+?^${}()|[\]\\]/g, "\\$&")).join("|")})`, "g");
  const parts = text.split(pattern);
  return (
    <>
      {parts.map((part, i) =>
        ABBREV_GLOSSARY[part] ? <span key={i} className="abbrev-chip-token-inline-plain">{part}</span> : <span key={i}>{part}</span>
      )}
    </>
  );
}

function ComparativeOfChip({ token, forms, chipId }) {
  const { expandedId, setExpandedId, toggleAnswerVisible, answerVisible } = useChipState();
  const tokenShown = expandedId === chipId;
  const expandedPosIndex = forms.findIndex((f, i) => expandedId === `compOfPos-${i}`);
  if (tokenShown) {
    const plainValue = forms.map(f => `${f.form} (${POS_LABEL[f.pos] || f.pos})`).join(" / ");
    const valueNode = (
      <>
        {forms.map((f, i) => (
          <span key={f.pos + i}>
            {i > 0 && " / "}
            {f.form}
            {" ("}
            <span className="inline-abbrev-chip" onClick={(e) => e.stopPropagation()}>
              <AbbrevChip token={POS_LABEL[f.pos] || f.pos} expandedId={expandedId} setExpandedId={setExpandedId} chipId={`compOfPos-${i}`} />
            </span>
            {")"}
          </span>
        ))}
      </>
    );
    return (
      <div className="top-chip-panel-below">
        <ExpandedAbbrevDetail token={token} chipId={chipId} onClose={() => setExpandedId(null)} value={plainValue} valueNode={valueNode} />
      </div>
    );
  }
  if (expandedPosIndex !== -1) {
    return (
      <div className="top-chip-panel-below">
        <ExpandedAbbrevDetail token={POS_LABEL[forms[expandedPosIndex].pos] || forms[expandedPosIndex].pos} chipId={`compOfPos-${expandedPosIndex}`} onClose={() => setExpandedId(null)} />
      </div>
    );
  }
  const isVisible = answerVisible.has(chipId);
  return (
    <span className="grammar-chip abbrev-reveal-chip comp-of-chip">
      <AbbrevChip token={token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={chipId} />
      {isVisible
        ? (
          <span className="reveal-value comp-of-forms" onClick={() => toggleAnswerVisible(chipId)}>
            {forms.map((f, i) => (
              <span key={f.pos + i}>
                {i > 0 && " / "}
                {f.form}
                {" ("}
                <span className="inline-abbrev-chip" onClick={(e) => e.stopPropagation()}>
                  <AbbrevChip token={POS_LABEL[f.pos] || f.pos} expandedId={expandedId} setExpandedId={setExpandedId} chipId={`compOfPos-${i}`} />
                </span>
                {")"}
              </span>
            ))}
          </span>
        )
        : <span className="reveal-colon-hint" onClick={() => toggleAnswerVisible(chipId)}>?</span>
      }
    </span>
  );
}


function AbbrevRevealChip({ token, value, chipId, showTranslation, isShortForm }) {
  const { expandedId, setExpandedId, toggleAnswerVisible, answerVisible } = useChipState();
  const answerId = chipId + "-answer";
  const tokenShown = expandedId === chipId;
  const answerShown = expandedId === answerId;
  if (tokenShown || answerShown) return null;
  const isVisible = answerVisible.has(chipId);
  const translation = showTranslation && isVisible ? governmentCaseNames(value) : null;
  const shortFormLines = isShortForm && isVisible ? formatShortForm(value) : null;
  const expandedLabelIndex = shortFormLines ? shortFormLines.findIndex((line, i) => expandedId === `shortFormLabel-${i}`) : -1;
  return (
    <>
      <span className="grammar-chip abbrev-reveal-chip">
        <AbbrevChip token={token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={chipId} />
        {isVisible
          ? (
            isShortForm
              ? <ShortFormLinesInline lines={shortFormLines} expandedId={expandedId} setExpandedId={setExpandedId} />
              : <span className="reveal-value" onClick={() => toggleAnswerVisible(chipId)}>{value}{translation && <span className="abbrev-note"> ({translation})</span>}</span>
          )
          : <span className="reveal-colon-hint" onClick={() => { toggleAnswerVisible(chipId); setExpandedId(answerId); }}>?</span>
        }
      </span>
      {expandedLabelIndex !== -1 && (
        <div className="top-chip-panel-below">
          <ExpandedAbbrevDetail token={shortFormLines[expandedLabelIndex].label} chipId={`shortFormLabel-${expandedLabelIndex}`} onClose={() => setExpandedId(null)} />
        </div>
      )}
    </>
  );
}

function CompactRevealCell({ token, value, chipId }) {
  const { expandedId, setExpandedId } = useChipState();
  const answerId = chipId + "-answer";
  const tokenShown = expandedId === chipId;
  const answerShown = expandedId === answerId;
  if (tokenShown || answerShown) return null;
  return (
    <span className="grammar-chip compact-reveal-chip" onClick={() => setExpandedId(answerId)}>
      <span className="reveal-colon-hint">?</span>
    </span>
  );
}

function LabelRevealChip({ label, value, chipId }) {
  const { expandedId, setExpandedId } = useChipState();
  const shown = expandedId === chipId;
  if (shown) return null;
  return (
    <span className="grammar-chip abbrev-reveal-chip">
      <span className="plain-label" onClick={() => setExpandedId(chipId)}>{label}:</span>
      <span className="reveal-colon-hint" onClick={() => setExpandedId(chipId)}>?</span>
    </span>
  );
}

function Reveal({ label, value }) {
  const [shown, setShown] = useState(false);
  return (
    <div className="grammar-detail-row">
      <span className="label reveal-label" onClick={() => setShown(v => !v)}>{label}:</span>
      {shown
        ? <span className="reveal-value"><AbbrevText text={value} /></span>
        : <span className="reveal-hidden" onClick={() => setShown(true)}>tap to reveal</span>
      }
    </div>
  );
}

function ExpandedAbbrevDetail({ token, chipId, onClose, value, showTranslation, wordLabel, pairAspectNoteNode, valueNode }) {
  const info = ABBREV_GLOSSARY[token];
  const { answerVisible, toggleAnswerVisible } = useChipState();
  if (!info) return null;
  const showingAnswer = chipId && answerVisible.has(chipId);
  const translation = showTranslation && showingAnswer ? governmentCaseNames(value) : null;
  const note = (token === "упр." && wordLabel) ? `the case(s) used with ${wordLabel}` : info.note;
  const useNoteNode = token === "вид. пара" && pairAspectNoteNode;
  const useShortFormNote = token === "кр.ф.";
  const isLitNote = note && note.startsWith("lit.");
  return (
    <div className="expanded-abbrev-panel">
      <div onClick={onClose}>
        <span className="abbrev-chip-ru">{info.ru}</span>
        {info.enOnNewLine
          ? <div className="abbrev-en-block">{info.en}</div>
          : <>{" — "}<span className="abbrev-en-inline">{info.en}</span></>
        }
        {useShortFormNote && (
          <div className="abbrev-note abbrev-note-block">
            (used in the construction "_ is <span className="abbrev-note-highlight">ill</span>", as opposed to "the <span className="abbrev-note-highlight">ill</span> _")
          </div>
        )}
        {!useShortFormNote && useNoteNode && <span className="abbrev-note"> ({pairAspectNoteNode})</span>}
        {!useShortFormNote && !useNoteNode && note && note.includes("\n") && (
          <div className="abbrev-note abbrev-note-block">
            {note.split("\n").map((line, i) => <div key={i}>{i === note.split("\n").length - 1 ? `(${line})` : line}</div>)}
          </div>
        )}
        {!useShortFormNote && !useNoteNode && note && !note.includes("\n") && (
          isLitNote
            ? <div className="abbrev-note abbrev-note-block">({note})</div>
            : <span className="abbrev-note"> ({note})</span>
        )}
      </div>
      {value && (
        <div className="panel-answer-row">
          {showingAnswer
            ? <span className="reveal-value" onClick={(e) => { e.stopPropagation(); toggleAnswerVisible(chipId); }}>{valueNode || value}{translation && <span className="abbrev-note"> ({translation})</span>}</span>
            : <span className={`reveal-colon-hint${chipId === "pairWord" ? " aspect-pair-question" : ""}`} onClick={(e) => { e.stopPropagation(); toggleAnswerVisible(chipId); }}>?</span>
          }
        </div>
      )}
    </div>
  );
}

// Government patterns as they actually appear in this dictionary — matched as
// whole normalized strings, since question words only make sense as pairs
// (e.g. "кого? что?" together means Accusative; they are NOT two separate cases).
// Government case detection. Bare (no-preposition) question-word PAIRS like
// "кого? что?" are a single conventional signal for one case (here: Accusative)
// — the individual words are each independently ambiguous (кого alone could be
// Genitive or Accusative) but the PAIR, as it's always written in dictionaries,
// disambiguates to exactly one case. Prepositions each pin down their own case
// regardless of which question word follows.
const BARE_PAIR_CASE = {
  "кто что": "Nominative",
  "кого чего": "Genitive",
  "кому чему": "Dative",
  "кого что": "Accusative",
  "кем чем": "Instrumental",
  "ком чём": "Prepositional",
};
const PREP_CASE = {
  "без кого": "Genitive", "без чего": "Genitive",
  "для кого": "Genitive", "для чего": "Genitive",
  "до кого": "Genitive", "до чего": "Genitive",
  "из кого": "Genitive", "из чего": "Genitive",
  "к кому": "Dative", "к чему": "Dative",
  "с кем": "Instrumental", "с чем": "Instrumental",
  "за кого": "Accusative", "за что": "Accusative",
  "о ком": "Prepositional", "о чём": "Prepositional",
  "в кого": "Accusative", "в что": "Accusative",
  "в ком": "Prepositional", "в чём": "Prepositional",
};
// куда/откуда are directional adverbs, not case-question words themselves —
// they don't have ONE fixed case the way кого/что do, since it depends on
// which preposition governs the destination/origin. These list the range of
// cases conventionally used, not a single definitive answer.
const DIRECTIONAL_CASE_HINT = {
  "куда": "Accusative or Dative",
  "откуда": "Genitive",
};

function governmentCaseNames(value) {
  if (!value) return null;
  const tokens = value.toLowerCase().replace(/\?/g, "").trim().split(/\s+/);
  const results = [];
  let i = 0;
  while (i < tokens.length) {
    const pairKey = tokens[i] + " " + (tokens[i + 1] || "");
    if (BARE_PAIR_CASE[pairKey]) {
      if (!results.includes(BARE_PAIR_CASE[pairKey])) results.push(BARE_PAIR_CASE[pairKey]);
      i += 2;
      continue;
    }
    if (PREP_CASE[pairKey]) {
      if (!results.includes(PREP_CASE[pairKey])) results.push(PREP_CASE[pairKey]);
      i += 2;
      continue;
    }
    if (DIRECTIONAL_CASE_HINT[tokens[i]]) {
      if (!results.includes(DIRECTIONAL_CASE_HINT[tokens[i]])) results.push(DIRECTIONAL_CASE_HINT[tokens[i]]);
      i += 1;
      continue;
    }
    i += 1;
  }
  return results.length ? results.join(", ") : null;
}

function formatShortForm(value) {
  // Source format: "masc, fem[, neut], мн.ч. plural" — comma-separated,
  // with the plural form always prefixed by "мн.ч." in the raw text.
  const parts = value.split(",").map(p => p.trim());
  const plIdx = parts.findIndex(p => p.startsWith("мн.ч."));
  const genderForms = plIdx === -1 ? parts : parts.slice(0, plIdx);
  const pluralForm = plIdx === -1 ? null : parts[plIdx].replace(/^мн\.ч\.\s*/, "");
  const genderLabels = ["м.р.", "ж.р.", "ср.р."]; // masc, fem, (neut if present)
  const lines = genderForms.map((form, i) => ({ label: genderLabels[i] || "?", form }));
  if (pluralForm) lines.push({ label: "мн.ч.", form: pluralForm });
  return lines;
}

function ShortFormLinesInline({ lines, expandedId, setExpandedId }) {
  return (
    <span className="abbrev-chip-ru short-form-lines">
      {lines.map((line, i) => (
        <span key={i}>
          <span className="inline-abbrev-chip short-form-label" onClick={(e) => e.stopPropagation()}>
            <AbbrevChip token={line.label} expandedId={expandedId} setExpandedId={setExpandedId} chipId={`shortFormLabel-${i}`} />
          </span>
          {": "}{line.form}
        </span>
      ))}
    </span>
  );
}

function ShortFormLines({ value }) {
  const { expandedId, setExpandedId } = useChipState();
  const shortFormLines = formatShortForm(value);
  const expandedLabelIndex = shortFormLines.findIndex((line, i) => expandedId === `shortFormLabel-${i}`);
  return (
    <>
      <ShortFormLinesInline lines={shortFormLines} expandedId={expandedId} setExpandedId={setExpandedId} />
      {expandedLabelIndex !== -1 && (
        <div className="top-chip-panel-below">
          <ExpandedAbbrevDetail token={shortFormLines[expandedLabelIndex].label} chipId={`shortFormLabel-${expandedLabelIndex}`} onClose={() => setExpandedId(null)} />
        </div>
      )}
    </>
  );
}

function ExpandedAnswerDetail({ label, value, onClose, showTranslation, isShortForm, onShowGlossary }) {
  const { expandedId, setExpandedId } = useChipState();
  const caseNames = showTranslation ? governmentCaseNames(value) : null;
  return (
    <div className="expanded-abbrev-panel expanded-answer-compact" onClick={onClose} style={{ cursor: "pointer" }}>
      {label && (
        <span
          className="plain-label-inline reveal-colon-hint-inline"
          onClick={onShowGlossary ? (e) => { e.stopPropagation(); onShowGlossary(); } : undefined}
        >
          {label}
        </span>
      )}
      {label && ": "}
      {isShortForm ? (
        <ShortFormLines value={value} />
      ) : (
        <span className="abbrev-chip-ru">{value}</span>
      )}
      {caseNames && <span className="abbrev-note"> ({caseNames})</span>}
    </div>
  );
}

// ---------- CHIP REGISTRY ----------
// Single source of truth for every grammar-fact chip: which zone it belongs to
// (top row next to "Correct!", or below the word), its fixed slot within that
// zone (for stable grid-row placement), and how to render its token/label,
// its answer value, and its expanded panel. This keeps "where does this
// chip's panel appear" a structural property instead of scattered logic.

function buildChipRegistry(word, showPos = true) {
  if (!word) return [];
  const items = [];
  const posEntry = { chipId: "pos", token: POS_LABEL[word.pos] || word.pos };

  // --- TOP ZONE ---
  if (word.pos === "noun" && word.gender) {
    const parts = [
      ...(showPos ? [posEntry] : []),
      { chipId: "gender", token: GENDER_ABBREV[word.gender], symbol: GENDER_SYMBOL[word.gender] },
    ];
    if (word.onlySingular) parts.push({ chipId: "onlySg", token: "только ед.ч." });
    if (word.onlyPlural) parts.push({ chipId: "onlyPl", token: "только мн.ч." });
    if (word.genitivePlural) parts.push({ chipId: "genPl", token: "р.п. мн.ч.", value: word.genitivePlural, isReveal: true });
    items.push({ zone: "below", slot: 0, chipId: "nounInfo", kind: "comboMulti", parts });
  } else if (word.pos === "noun" && (word.onlySingular || word.onlyPlural)) {
    const parts = showPos ? [posEntry] : [];
    if (word.onlySingular) parts.push({ chipId: "onlySg", token: "только ед.ч." });
    if (word.onlyPlural) parts.push({ chipId: "onlyPl", token: "только мн.ч." });
    if (word.genitivePlural) parts.push({ chipId: "genPl", token: "р.п. мн.ч.", value: word.genitivePlural, isReveal: true });
    items.push({ zone: "below", slot: 0, chipId: "nounInfo", kind: "comboMulti", parts });
  } else if (word.pos === "verb" && (word.aspect || word.government || word.conjGroup || word.thirdPersonOnly)) {
    const parts = showPos ? [posEntry] : [];
    if (word.aspect) parts.push({ chipId: "aspect", token: ASPECT_ABBREV[word.aspect], aspectClass: word.aspect });
    if (word.conjGroup) parts.push({ chipId: "conj", token: word.conjGroup });
    if (word.thirdPersonOnly) parts.push({ chipId: "thirdPersonOnly", token: "1 и 2 л. не употр." });
    if (word.government) parts.push({ chipId: "gov", token: "упр.", value: word.government, translate: true, isReveal: true });
    if (parts.length > 0) items.push({ zone: "top", slot: 0, kind: "comboMulti", parts });
  } else if (word.posAlt) {
    if (showPos) {
      items.push({ zone: "top", slot: 0, kind: "abbrev", chipId: "pos", token: POS_LABEL[word.pos] || word.pos });
      items.push({ zone: "top", slot: 0.4, kind: "slashMarker" });
      items.push({ zone: "top", slot: 0.5, kind: "abbrev", chipId: "posAlt", token: POS_LABEL[word.posAlt] || word.posAlt });
    }
  } else {
    if (showPos) items.push({ zone: "top", slot: 0, kind: "abbrev", chipId: "pos", token: POS_LABEL[word.pos] || word.pos });
    if (word.gender) {
      items.push({ zone: "top", slot: 1, kind: "abbrev", chipId: "gender", token: GENDER_ABBREV[word.gender], symbol: GENDER_SYMBOL[word.gender] });
    }
    if (word.aspect) items.push({ zone: "top", slot: 2, kind: "abbrev", chipId: "aspect", token: ASPECT_ABBREV[word.aspect], aspectClass: word.aspect });
    if (word.government) items.push({ zone: "top", slot: 7, kind: "abbrevReveal", chipId: "gov", token: "упр.", value: word.government, translate: true });
  }
  const hasTenseData = word.irregularForms || word.pastTense || word.pairIrregularForms || word.pairPastTense;
  const willHaveTenseGrid = word.pairStressed || hasTenseData;
  if (word.onlySingular && word.pos !== "noun") items.push({ zone: "top", slot: 3, kind: "abbrev", chipId: "onlySg", token: "только ед.ч." });
  if (word.onlyPlural && word.pos !== "noun") items.push({ zone: "top", slot: 4, kind: "abbrev", chipId: "onlyPl", token: "только мн.ч." });
  if (word.rareSingular) items.push({ zone: "top", slot: 4.6, kind: "abbrevReveal", chipId: "rareSg", token: "ед.ч.", value: word.rareSingular });
  if (word.genitivePlural && !(word.pos === "noun" && (word.gender || word.onlySingular || word.onlyPlural))) items.push({ zone: "top", slot: 5, kind: "abbrevReveal", chipId: "genPl", token: "р.п. мн.ч.", value: word.genitivePlural });

  // --- BELOW ZONE ---
  if (willHaveTenseGrid) {
    items.push({
      zone: "below", slot: 1, kind: "tenseGrid", chipId: "tenseGrid",
      thisVerbLabel: word.ruStressed,
      pairLabel: word.pairStressed || null,
      aspect: word.aspect || null,
      cells: {
        thisPres: word.irregularForms || null,
        thisPast: word.pastTense || null,
        pairPres: word.pairIrregularForms || null,
        pairPast: word.pairPastTense || null,
      },
    });
  }
  if (word.pluralIrregular) items.push({ zone: "below", slot: 6, kind: "abbrevReveal", chipId: "plural", token: "мн.ч.", value: word.pluralIrregular });
  if (word.shortForm && word.shortFormText) items.push({ zone: "below", slot: 7, kind: "abbrevReveal", chipId: "shortForm", token: "кр.ф.", value: word.shortFormText });
  if (word.comparative && word.comparativeOfForms) {
    items.push({ zone: "below", slot: 8, kind: "comparativeOf", chipId: "compOf", token: "сравн.ст.", forms: word.comparativeOfForms });
  }

  return items;
}

function renderComboMulti(item, expandedId, setExpandedId, expandedMultiPart, answerVisible, toggleAnswerVisible) {
  const visibleParts = item.parts.filter(part => part !== expandedMultiPart);
  return (
    <span key={item.parts.map(p => p.chipId).join("-")} className={`chip-slot slot-${item.slot}`}>
      {visibleParts.map((part, i) => {
        const posClass = visibleParts.length === 1 ? "combo-solo" : i === 0 ? "combo-left" : i === visibleParts.length - 1 ? "combo-right" : "combo-mid";
        const isPartVisible = part.isReveal && answerVisible && answerVisible.has(part.chipId);
        return (
          <span key={part.chipId} className={`grammar-chip ${posClass}${part.aspectClass ? ` aspect-${part.aspectClass}` : ""}${part.symbol ? " gender-row" : ""}`}>
            {part.symbol && <span className="gender-symbol">{part.symbol}</span>}
            {part.isReveal ? (
              <span className="combo-part-reveal">
                <AbbrevChip token={part.token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={part.chipId} />
                {" "}
                {isPartVisible
                  ? <span className="reveal-value" onClick={() => toggleAnswerVisible(part.chipId)}>{part.value}</span>
                  : <span className="upr-question" onClick={() => setExpandedId(part.chipId + "-answer")}><span className="reveal-colon-hint">?</span></span>
                }
              </span>
            ) : (
              <AbbrevChip token={part.token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={part.chipId} />
            )}
          </span>
        );
      })}
    </span>
  );
}

function renderComboMultiPanel(expandedMultiPart, expandedId, setExpandedId) {
  if (expandedMultiPart.isReveal) {
    return renderChipPanel({ kind: "abbrevReveal", chipId: expandedMultiPart.chipId, token: expandedMultiPart.token, value: expandedMultiPart.value, translate: expandedMultiPart.translate }, expandedId, setExpandedId);
  }
  return <ExpandedAbbrevDetail token={expandedMultiPart.token} chipId={expandedMultiPart.chipId} onClose={() => setExpandedId(null)} />;
}

function renderChipToken(item, expandedId, setExpandedId) {
  if (item.kind === "abbrev") {
    return (
      <span className={`grammar-chip${item.aspectClass ? ` aspect-${item.aspectClass}` : ""}${item.symbol ? " gender-row" : ""}`}>
        {item.symbol && <span className="gender-symbol">{item.symbol}</span>}
        <AbbrevChip token={item.token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={item.chipId} />
      </span>
    );
  }
  if (item.kind === "abbrevReveal") {
    return <AbbrevRevealChip token={item.token} value={item.value} chipId={item.chipId} showTranslation={item.translate} isShortForm={item.chipId === "shortForm"} />;
  }
  if (item.kind === "labelReveal") {
    return <LabelRevealChip label={item.label} value={item.value} expandedId={expandedId} setExpandedId={setExpandedId} chipId={item.chipId} />;
  }
  if (item.kind === "tenseGrid") {
    return <TenseGrid item={item} />;
  }
  if (item.kind === "comparativeOf") {
    return <ComparativeOfChip token={item.token} forms={item.forms} chipId={item.chipId} />;
  }
  return null;
}

function AspectPairInline({ word }) {
  const { expandedId, setExpandedId, answerVisible, toggleAnswerVisible } = useChipState();
  if (!word.pairStressed) return null;
  const pairChipId = "pairWord";
  const isVisible = answerVisible.has(pairChipId);
  const tokenExpanded = expandedId === pairChipId;
  const pairAspect = word.aspect === "impf" ? "pf" : word.aspect === "pf" ? "impf" : null;
  if (tokenExpanded) return null;
  return (
    <div className="aspect-pair-inline">
      {!isVisible && (
        <>
          {"⇄ "}
          <span className="aspect-pair-label" onClick={() => setExpandedId(pairChipId)}>(вид. пара)</span>
          {": "}
          <span className="reveal-colon-hint aspect-pair-question" onClick={() => toggleAnswerVisible(pairChipId)}>?</span>
        </>
      )}
      {isVisible
        ? (
          <span className="aspect-pair-revealed" onClick={() => toggleAnswerVisible(pairChipId)}>
            {"⇄ "}{word.pairStressed}
            {pairAspect && (
              <span className="aspect-pair-tag">
                {" ("}
                <span className="inline-abbrev-chip" onClick={(e) => e.stopPropagation()}>
                  <AbbrevChip token={ASPECT_ABBREV[pairAspect]} expandedId={expandedId} setExpandedId={setExpandedId} chipId="pairAspect" />
                </span>
                {")"}
              </span>
            )}
          </span>
        )
        : null
      }
    </div>
  );
}

function AspectPairPanel({ word }) {
  const { expandedId, setExpandedId } = useChipState();
  if (!word.pairStressed) return null;
  const pairChipId = "pairWord";
  const showingPairAspect = expandedId === "pairAspect";
  if (expandedId !== pairChipId && !showingPairAspect) return null;
  const pairAspect = word.aspect === "impf" ? "pf" : word.aspect === "pf" ? "impf" : null;
  if (showingPairAspect && pairAspect) {
    return (
      <div className="aspect-pair-panel-below">
        <ExpandedAbbrevDetail token={ASPECT_ABBREV[pairAspect]} chipId="pairAspect" onClose={() => setExpandedId(null)} />
      </div>
    );
  }
  return (
    <div className="aspect-pair-panel-below">
      <ExpandedAbbrevDetail
        token="вид. пара"
        chipId={pairChipId}
        onClose={() => setExpandedId(null)}
        value={word.pairStressed}
        pairAspectNoteNode={pairAspect && (
          <>
            {"the "}
            <span className="inline-abbrev-chip" onClick={(e) => e.stopPropagation()}>
              <AbbrevChip token={ASPECT_ABBREV[pairAspect]} expandedId={expandedId} setExpandedId={setExpandedId} chipId="pairAspect" />
            </span>
            {" pair of "}{word.ruStressed}
          </>
        )}
      />
    </div>
  );
}

function MotionDirectionHint({ direction }) {
  const [showRu, setShowRu] = useState(false);
  const enLabel = direction === "uni" ? "(unidirectional)" : "(multidirectional)";
  const ruLabel = direction === "uni" ? "(однонаправленное)" : "(разнонаправленное)";
  return (
    <span className="motion-direction-hint" onClick={(e) => { e.stopPropagation(); setShowRu(v => !v); }}>
      {" "}{showRu ? ruLabel : enLabel}
    </span>
  );
}

function TenseGrid({ item }) {
  const { pairLabel, cells, aspect } = item;
  const hasAny = cells.thisPres || cells.thisPast || cells.pairPres || cells.pairPast;
  if (!hasAny) return null;
  const hasPresent = cells.thisPres || cells.pairPres;
  const hasPast = cells.thisPast || cells.pairPast;
  // A verb's own conjugated non-past forms are present tense only if it's
  // imperfective. Its aspectual pair is always the opposite aspect, so if
  // THIS verb is imperfective, the pair (perfective) has no present tense —
  // those same-looking conjugated forms are future tense instead.
  const thisIsPerfective = aspect === "pf";
  const pairIsPerfective = aspect === "impf";
  const thisPresLabel = thisIsPerfective ? "буд.вр." : "наст.вр.";
  const pairPresLabel = pairIsPerfective ? "буд.вр." : "наст.вр.";
  const columnTemplate = pairLabel ? "1fr 1fr" : "1fr";
  return (
    <div className="tense-columns-wrap">
      <div className="tense-grid-fixed" style={{ gridTemplateColumns: columnTemplate }}>
        {(cells.thisPres || cells.thisPast) && <div className="tense-column-connector" style={{ gridRow: 2, gridColumn: 1 }}>↓</div>}
        {pairLabel && (cells.pairPres || cells.pairPast) && <div className="tense-column-connector" style={{ gridRow: 2, gridColumn: 2 }}>↓</div>}
        {hasPresent && (
          <>
            <TenseFixedCell cellId="presTense" value={cells.thisPres} gridRow={3} gridColumn={1} label={thisPresLabel} row="top" />
            <TenseFixedCell cellId="pairPresTense" value={cells.pairPres} gridRow={3} gridColumn={2} show={!!pairLabel} label={pairPresLabel} row="top" />
          </>
        )}
        {hasPast && (
          <>
            <TenseFixedCell cellId="pastTense" value={cells.thisPast} gridRow={4} gridColumn={1} label="прош.вр." row="bottom" />
            <TenseFixedCell cellId="pairPastTense" value={cells.pairPast} gridRow={4} gridColumn={2} show={!!pairLabel} label="прош.вр." row="bottom" />
          </>
        )}
      </div>
    </div>
  );
}

function AbbrevChipStandalone({ token }) {
  const { expandedId, setExpandedId } = useChipState();
  const chipId = "label-" + token;
  return <AbbrevChip token={token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={chipId} />;
}

function TenseFixedCell({ cellId, value, gridRow, gridColumn, show = true, label, row }) {
  const { expandedId, setExpandedId, answerVisible, toggleAnswerVisible } = useChipState();
  if (!show) return <div style={{ gridRow, gridColumn }} />;
  if (!value) return <div className="tense-fixed-box tense-fixed-empty" style={{ gridRow, gridColumn }} />;
  const isVisible = answerVisible.has(cellId);
  const labelChipId = "label-" + label;
  const labelExpanded = expandedId === labelChipId;
  const cellBox = (
    <div className="tense-fixed-box">
      {isVisible ? (
        <span className="tense-fixed-value" onClick={() => toggleAnswerVisible(cellId)}>
          {value.split(",").map((part, i) => <span key={i}>{part.trim()}</span>)}
        </span>
      ) : (
        <span className="tense-fixed-collapsed">
          {label && (
            <span className="inline-abbrev-chip" onClick={(e) => e.stopPropagation()}>
              <AbbrevChip token={label} expandedId={expandedId} setExpandedId={setExpandedId} chipId={labelChipId} />
            </span>
          )}
          {" "}
          <span className="reveal-colon-hint" onClick={() => toggleAnswerVisible(cellId)}>?</span>
        </span>
      )}
    </div>
  );
  const bareCellBox = (
    <div className="tense-fixed-box">
      {isVisible ? (
        <span className="tense-fixed-value" onClick={() => toggleAnswerVisible(cellId)}>
          {value.split(",").map((part, i) => <span key={i}>{part.trim()}</span>)}
        </span>
      ) : (
        <span className="tense-fixed-collapsed">
          <span className="reveal-colon-hint" onClick={() => toggleAnswerVisible(cellId)}>?</span>
        </span>
      )}
    </div>
  );
  if (labelExpanded) {
    const panelRow = row === "top" ? 1 : 5;
    return (
      <>
        <div style={{ gridRow, gridColumn }}>{bareCellBox}</div>
        <div className="tense-grid-panel-outward" style={{ gridRow: panelRow, gridColumn: "1 / -1" }}>
          <ExpandedAbbrevDetail token={label} chipId={labelChipId} onClose={() => setExpandedId(null)} />
        </div>
      </>
    );
  }
  return (
    <div className="tense-cell-wrap" style={{ gridRow, gridColumn }}>
      {isVisible && label && (
        <span
          className="tense-cell-label-above"
          onClick={(e) => { e.stopPropagation(); setExpandedId(labelChipId); }}
        >
          {label}
        </span>
      )}
      {cellBox}
    </div>
  );
}


function renderChipPanel(item, expandedId, setExpandedId, wordLabel) {
  const answerId = item.chipId + "-answer";
  if (expandedId === item.chipId) {
    // token itself expanded -> glossary explanation, with optional answer toggle
    const token = item.kind === "combo" ? null : item.token;
    if (!token) return null;
    const isShortForm = item.chipId === "shortForm";
    const shortFormValueNode = isShortForm && item.value ? (
      <ShortFormLines value={item.value} />
    ) : null;
    return (
      <ExpandedAbbrevDetail
        token={token}
        chipId={item.chipId}
        onClose={() => setExpandedId(null)}
        value={item.kind === "abbrevReveal" ? item.value : null}
        valueNode={shortFormValueNode}
        showTranslation={item.translate}
        wordLabel={wordLabel}
      />
    );
  }
  if (expandedId === answerId && (item.kind === "abbrevReveal")) {
    const label = item.token;
    return (
      <ExpandedAnswerDetail
        label={label}
        value={item.value}
        onClose={() => setExpandedId(null)}
        showTranslation={item.translate}
        isShortForm={item.chipId === "shortForm"}
        onShowGlossary={() => setExpandedId(item.chipId)}
      />
    );
  }
  if (expandedId === item.chipId && item.kind === "labelReveal") {
    return <ExpandedAnswerDetail label={item.label} value={item.value} onClose={() => setExpandedId(null)} />;
  }
  return null;
}

function TopChipRow({ word }) {
  const { expandedId, setExpandedId, answerVisible, toggleAnswerVisible, showPos } = useChipState();
  const items = buildChipRegistry(word, showPos).filter(i => i.zone === "top");
  if (items.length === 0) return null;

  // A combo item (POS+gender, or POS+aspect+government for verbs) is really
  // N independent chips visually joined. Each part can expand on its own
  // while the others stay put.
  const comboItem = items.find(i => i.kind === "combo");
  const comboMultiItem = items.find(i => i.kind === "comboMulti");
  const expandedNonCombo = items.find(i =>
    i.kind !== "combo" && i.kind !== "comboMulti" && (
      expandedId === i.chipId ||
      (i.kind === "abbrevReveal" && expandedId === i.chipId + "-answer")
    )
  );
  const comboLeftExpanded = comboItem && expandedId === comboItem.left.chipId;
  const comboRightExpanded = comboItem && expandedId === comboItem.right.chipId;
  const expandedMultiPart = comboMultiItem && comboMultiItem.parts.find(p =>
    expandedId === p.chipId || (p.isReveal && expandedId === p.chipId + "-answer")
  );

  return (
    <>
      <div className="chip-row-right">
        {items.map(item => {
          if (item.kind === "slashMarker") {
            return <span key="slashMarker" className="pos-slash-standalone">/</span>;
          }
          if (item.kind === "abbrev" || item.kind === "abbrevReveal" || item.kind === "labelReveal") {
            const isExpanded = item === expandedNonCombo;
            if (isExpanded) return null;
            return (
              <span key={item.chipId} className={`chip-slot slot-${item.slot}${item.slashAfter ? " chip-slot-slash-after" : ""}`}>
                {renderChipToken(item, expandedId, setExpandedId)}
              </span>
            );
          }
          if (item.kind === "comboMulti") {
            return renderComboMulti(item, expandedId, setExpandedId, expandedMultiPart, answerVisible, toggleAnswerVisible);
          }
          // legacy 2-part combo (noun POS+gender)
          return (
            <span key={`${item.left.chipId}-${item.right.chipId}`} className={`chip-slot slot-${item.slot}`}>
              {!comboLeftExpanded && (
                <span className="grammar-chip combo-left">
                  <AbbrevChip token={item.left.token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={item.left.chipId} />
                </span>
              )}
              {!comboRightExpanded && (
                <span className="grammar-chip combo-right gender-row">
                  <span className="gender-symbol">{item.right.symbol}</span>
                  <AbbrevChip token={item.right.token} expandedId={expandedId} setExpandedId={setExpandedId} chipId={item.right.chipId} />
                </span>
              )}
            </span>
          );
        })}
      </div>
      {expandedNonCombo && (
        <div className="top-chip-panel-below">
          {renderChipPanel(expandedNonCombo, expandedId, setExpandedId, word.ruStressed)}
        </div>
      )}
      {expandedMultiPart && (
        <div className="top-chip-panel-below">
          {expandedMultiPart.isReveal
            ? renderChipPanel({ kind: "abbrevReveal", chipId: expandedMultiPart.chipId, token: expandedMultiPart.token, value: expandedMultiPart.value, translate: expandedMultiPart.translate }, expandedId, setExpandedId, word.ruStressed)
            : <ExpandedAbbrevDetail token={expandedMultiPart.token} chipId={expandedMultiPart.chipId} onClose={() => setExpandedId(null)} />
          }
        </div>
      )}      {comboLeftExpanded && (
        <div className="top-chip-panel-below">
          <ExpandedAbbrevDetail token={comboItem.left.token} chipId={comboItem.left.chipId} onClose={() => setExpandedId(null)} />
        </div>
      )}
      {comboRightExpanded && (
        <div className="top-chip-panel-below">
          <ExpandedAbbrevDetail token={comboItem.right.token} chipId={comboItem.right.chipId} onClose={() => setExpandedId(null)} />
        </div>
      )}
    </>
  );
}

const BELOW_ZONE_CHIP_ORDER = [
  "nounInfo", "gov", "tenseGrid", "plural", "shortForm", "compOf",
];

function BelowWordDetails({ word }) {
  const { expandedId, setExpandedId, answerVisible, toggleAnswerVisible, showPos } = useChipState();
  const items = buildChipRegistry(word, showPos).filter(i => i.zone === "below");
  if (items.length === 0) return null;
  const itemsById = {};
  items.forEach(i => { itemsById[i.chipId] = i; });
  return (
    <div className="below-word-chips">
      {BELOW_ZONE_CHIP_ORDER.map(id => {
        const item = itemsById[id];
        if (!item) return null; // this word simply has no such fact — no slot at all
        if (item.kind === "comboMulti") {
          const expandedMultiPart = item.parts.find(p =>
            expandedId === p.chipId || (p.isReveal && expandedId === p.chipId + "-answer")
          );
          return (
            <div key={id} className={`row-${id}`}>
              {renderComboMulti(item, expandedId, setExpandedId, expandedMultiPart, answerVisible, toggleAnswerVisible)}
              {expandedMultiPart && (
                <div className="top-chip-panel-below">
                  {renderComboMultiPanel(expandedMultiPart, expandedId, setExpandedId)}
                </div>
              )}
            </div>
          );
        }
        if (item.kind === "comparativeOf") {
          return (
            <div key={id} className={`row-${id}`}>
              {renderChipToken(item, expandedId, setExpandedId)}
            </div>
          );
        }
        const isExpanded = expandedId === item.chipId ||
          (item.kind === "abbrevReveal" && expandedId === item.chipId + "-answer");
        return (
          <div key={id} className={`row-${id}`} style={isExpanded ? { width: "100%", alignSelf: "stretch" } : undefined}>
            {isExpanded
              ? renderChipPanel(item, expandedId, setExpandedId, word.ruStressed)
              : renderChipToken(item, expandedId, setExpandedId)
            }
          </div>
        );
      })}
    </div>
  );
}
// ---------- END CHIP REGISTRY ----------

function GrammarCard({ word, inline }) {
  if (!word) return null;
  if (!word.usageExampleRu) return null;
  return (
    <div className={inline ? "grammar-card-inline" : "grammar-card"}>
      <Reveal label="example" value={`${word.usageExampleRu} — ${word.usageExampleEn}`} />
    </div>
  );
}

export default function RussianApp({ theme, setTheme, onSwitchLanguage }) {
  const [level, setLevel] = useState("B1");
  const [levelMenuOpen, setLevelMenuOpen] = useState(false);
  const [languageMenuOpen, setLanguageMenuOpen] = useState(false);
  const RU_WORDS = LEVELS[level].words;
  const [mode, setMode] = useState(null);
  const [isBadListSession, setIsBadListSession] = useState(false);
  const [pool, setPool] = useState([]);
  const [index, setIndex] = useState(0);
  const [input, setInput] = useState("");
  const [mcChoices, setMcChoices] = useState([]);
  const [result, setResult] = useState(null);
  const [correctAns, setCorrectAns] = useState("");
  const [score, setScore] = useState({ correct: 0, total: 0 });
  const [done, setDone] = useState(false);
  const [chosen, setChosen] = useState(null);
  const [chipExpandedId, setChipExpandedId] = useState(null);
  const showPos = true;
  const [answerVisible, setAnswerVisible] = useState(() => new Set());
  function toggleAnswerVisible(chipId) {
    setAnswerVisible(prev => {
      const next = new Set(prev);
      if (next.has(chipId)) next.delete(chipId); else next.add(chipId);
      return next;
    });
  }
  const [badList, setBadList] = useState(GLOBAL_STATE[level].badList);
  const [mastery, setMastery] = useState(GLOBAL_STATE[level].mastery);
  const [rangeStart, setRangeStart] = useState(0);
  const [rangeEnd, setRangeEnd] = useState(RU_WORDS.length - 1);
  const [roundSize, setRoundSize] = useState(TOTAL);
  const [loading, setLoading] = useState(true);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [licenseOpen, setLicenseOpen] = useState(false);
  const [challengeThreshold, setChallengeThreshold] = useState(4);
  const [challengeFilter, setChallengeFilter] = useState(false);
  const [editingThreshold, setEditingThreshold] = useState(false);
  const [distributeOrder, setDistributeOrder] = useState(false);
  const [dragAnchorIdx, setDragAnchorIdx] = useState(null);
  const dragBaseRef = useRef(0);
  const orderedWords = useMemo(() => {
    if (!distributeOrder) return RU_WORDS;
    const groups = Array.from({ length: 10 }, () => []);
    RU_WORDS.forEach((w, i) => { groups[(i + 1) % 10].push(w); });
    return [1, 2, 3, 4, 5, 6, 7, 8, 9, 0].flatMap(d => groups[d]);
  }, [RU_WORDS, distributeOrder]);

  useEffect(() => {
    loadStorage(level).then(({ badList, mastery }) => {
      GLOBAL_STATE[level] = { badList, mastery };
      setBadList([...badList]);
      setMastery({ ...mastery });
      setLoading(false);
    });
  }, [level]);

  function selectLevel(newLevel) {
    if (newLevel === level) { setLevelMenuOpen(false); return; }
    setLevelMenuOpen(false);
    setLoading(true);
    setMode(null); setIsBadListSession(false); setPool([]); setIndex(0);
    setInput(""); setMcChoices([]); setResult(null); setCorrectAns("");
    setScore({ correct: 0, total: 0 }); setDone(false); setChosen(null);
    setChipExpandedId(null); setAnswerVisible(new Set());
    setChallengeFilter(false); setEditingThreshold(false); setDistributeOrder(false);
    setRangeStart(0);
    setRangeEnd(LEVELS[newLevel].words.length - 1);
    setRoundSize(TOTAL);
    setLevel(newLevel);
  }

  const nextBtnRef = useRef(null);
  useEffect(() => {
    if (result && nextBtnRef.current) {
      nextBtnRef.current.scrollIntoView({ behavior: "smooth", block: "end" });
    }
  }, [result]);

  function removeFromBadList(word) {
    GLOBAL_STATE[level].badList = GLOBAL_STATE[level].badList.filter(w => w.ru !== word.ru);
    setBadList([...GLOBAL_STATE[level].badList]);
    saveStorage(level, GLOBAL_STATE[level].badList, GLOBAL_STATE[level].mastery);
  }
  function addToBadList(word) {
    if (!GLOBAL_STATE[level].badList.find(w => w.ru === word.ru)) {
      GLOBAL_STATE[level].badList = [...GLOBAL_STATE[level].badList, word];
      setBadList([...GLOBAL_STATE[level].badList]);
      saveStorage(level, GLOBAL_STATE[level].badList, GLOBAL_STATE[level].mastery);
    }
  }
  function clearBadList() {
    GLOBAL_STATE[level].badList = [];
    setBadList([]);
    saveStorage(level, [], GLOBAL_STATE[level].mastery);
  }
  function recordAnswer(word, correct) {
    const prev = GLOBAL_STATE[level].mastery[word.ru] || { seen: 0, lastCorrect: false, timesOnBadList: 0, correctStreak: 0, lastPracticedAt: 0 };
    GLOBAL_STATE[level].mastery = {
      ...GLOBAL_STATE[level].mastery,
      [word.ru]: {
        seen: prev.seen + 1,
        lastCorrect: correct,
        timesOnBadList: correct ? (prev.timesOnBadList || 0) : (prev.timesOnBadList || 0) + 1,
        correctStreak: correct ? (prev.correctStreak || 0) + 1 : 0,
        lastPracticedAt: Date.now(),
      }
    };
    setMastery({ ...GLOBAL_STATE[level].mastery });
    saveStorage(level, GLOBAL_STATE[level].badList, GLOBAL_STATE[level].mastery);
    if (correct) { removeFromBadList(word); } else { addToBadList(word); }
  }

  const masteredCount = Object.values(mastery).filter(m => m.lastCorrect === true).length;
  const seenCount = Object.keys(mastery).length;
  const totalWords = RU_WORDS.length;
  const SUBRANGE_MARKS = [0, 20, 40, 60, 80, 100];
  function applyBlockRange(base, startIdx, endIdx) {
    const lo = Math.min(startIdx, endIdx);
    const hi = Math.max(startIdx, endIdx);
    setRangeStart(Math.min(base + SUBRANGE_MARKS[lo], totalWords - 1));
    setRangeEnd(Math.min(base + SUBRANGE_MARKS[hi + 1] - 1, totalWords - 1));
  }
  useEffect(() => {
    if (dragAnchorIdx === null) return;
    function handleMove(e) {
      const point = e.touches ? e.touches[0] : e;
      const el = document.elementFromPoint(point.clientX, point.clientY);
      const dotEl = el && el.closest && el.closest("[data-dot-index]");
      if (dotEl) {
        applyBlockRange(dragBaseRef.current, dragAnchorIdx, Number(dotEl.getAttribute("data-dot-index")));
      }
    }
    function handleUp() { setDragAnchorIdx(null); }
    window.addEventListener("pointermove", handleMove);
    window.addEventListener("pointerup", handleUp);
    window.addEventListener("pointercancel", handleUp);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      window.removeEventListener("pointerup", handleUp);
      window.removeEventListener("pointercancel", handleUp);
    };
  }, [dragAnchorIdx]);
  function getChallengingWords(fromList) {
    const base = fromList || orderedWords;
    return base
      .filter(w => {
        const m = GLOBAL_STATE[level].mastery[w.ru];
        return m && (m.timesOnBadList || 0) >= challengeThreshold && (m.correctStreak || 0) < 3;
      })
      .sort((a, b) => (GLOBAL_STATE[level].mastery[a.ru].lastPracticedAt || 0) - (GLOBAL_STATE[level].mastery[b.ru].lastPracticedAt || 0));
  }

  function buildMC(p, i) {
    const wrong = getWrongChoices(RU_WORDS, p[i], 3);
    setMcChoices(shuffle([p[i], ...wrong]));
  }

  function startQuiz(m, existingPool, badListSession = false) {
    let p = existingPool;
    if (!p) {
      const rangeWords = orderedWords.slice(rangeStart, rangeEnd + 1);
      const eligible = challengeFilter
        ? getChallengingWords(rangeWords).slice(0, roundSize)
        : rangeWords;
      p = shuffle(eligible).slice(0, Math.min(roundSize, eligible.length));
    }
    if (p.length === 0) return;
    setPool(p); setMode(m); setIsBadListSession(badListSession);
    setIndex(0); setScore({ correct: 0, total: 0 }); setResult(null);
    setInput(""); setDone(false); setChosen(null); setChipExpandedId(null); setAnswerVisible(new Set());
    if (m === "mc") buildMC(p, 0);
  }

  function startBadList(m) {
    if (GLOBAL_STATE[level].badList.length === 0) return;
    startQuiz(m, shuffle([...GLOBAL_STATE[level].badList]), true);
  }

  function replay() { startQuiz(mode, pool, isBadListSession); }

  function advance() {
    const next = index + 1;
    if (next >= pool.length) { setDone(true); return; }
    setIndex(next); setResult(null); setInput(""); setChosen(null); setChipExpandedId(null); setAnswerVisible(new Set());
    if (mode === "mc") buildMC(pool, next);
  }

  function checkTyped() {
    const cur = pool[index];
    let ans, correct;
    if (mode === "en-to-ru") {
      ans = cur.ru;
      correct = normalizeNoStress(input) === normalizeNoStress(ans);
    } else if (mode === "en-to-ru-stress") {
      ans = cur.ruTyping;
      correct = normalizeWithStress(input) === normalizeWithStress(ans);
    } else {
      ans = cur.en;
      const opts = ans.replace(/\(.*?\)/g, "").split(/[,;]/).map(s => normalizeEn(s));
      correct = opts.some(o => normalizeEn(input) === o) || normalizeEn(input) === normalizeEn(ans);
    }
    setCorrectAns(ans);
    setResult(correct ? "correct" : "wrong");
    setScore(s => ({ correct: s.correct + (correct ? 1 : 0), total: s.total + 1 }));
    recordAnswer(cur, correct);
  }

  function checkMC(choiceIdx) {
    if (result) return;
    const cur = pool[index];
    const choice = mcChoices[choiceIdx];
    setChosen(choiceIdx);
    const correct = choice.ru === cur.ru;
    setCorrectAns(cur.ruStressed);
    setResult(correct ? "correct" : "wrong");
    setScore(s => ({ correct: s.correct + (correct ? 1 : 0), total: s.total + 1 }));
    recordAnswer(cur, correct);
  }

  const cur = pool[index];
  const poolSize = pool.length || roundSize;
  const pct = done ? Math.round((score.correct / score.total) * 100) : 0;
  const progress = poolSize ? (index / poolSize) * 100 : 0;
  const currentBadList = GLOBAL_STATE[level].badList;

  if (loading) return (
    <>
      <style>{STYLES}</style>
      <div className="app">
        <div className="title">Русский {LEVELS[level].cyr}</div>
        <div style={{ color: "var(--muted-strong)", fontSize: "0.7rem", letterSpacing: "0.2em", marginTop: 16 }}>LOADING PROGRESS…</div>
      </div>
    </>
  );

  if (!mode) return (
    <>
      <style>{STYLES}</style>
      <div className="app">
        <div className="top-bar">
          <div className="top-bar-stack">
            <button
              type="button"
              className={`theme-toggle${theme === "light" ? " is-light" : ""}`}
              onClick={() => setTheme(t => t === "dark" ? "light" : "dark")}
              aria-label={theme === "dark" ? "Switch to light theme" : "Switch to dark theme"}
            >
              <span className="theme-toggle-knob">{theme === "dark" ? "🌙" : "☀️"}</span>
            </button>
          </div>
        </div>
        {settingsOpen && !licenseOpen && (
          <div className="modal-overlay" onClick={() => setSettingsOpen(false)}>
            <div className="modal-card" onClick={e => e.stopPropagation()}>
              <div className="modal-header">
                <span className="modal-title">SETTINGS</span>
                <button type="button" className="modal-close" onClick={() => setSettingsOpen(false)} aria-label="Close settings">×</button>
              </div>
              <button type="button" className="settings-item" onClick={() => setLicenseOpen(true)}>
                Licences
              </button>
            </div>
          </div>
        )}
        {settingsOpen && licenseOpen && (
          <div className="modal-overlay" onClick={() => { setLicenseOpen(false); setSettingsOpen(false); }}>
            <div className="modal-card" onClick={e => e.stopPropagation()}>
              <div className="modal-header">
                <span className="modal-title">LICENCES</span>
                <button type="button" className="modal-close" onClick={() => { setLicenseOpen(false); setSettingsOpen(false); }} aria-label="Close">×</button>
              </div>
              <div className="license-text">{APP_LICENSE_TEXT}</div>
            </div>
          </div>
        )}
        <div className="title">Русский {LEVELS[level].cyr}</div>
        <div className="subtitle">
          <button
            type="button"
            className="icon-btn subtitle-settings-btn"
            onClick={() => setSettingsOpen(true)}
            aria-label="Settings"
          >
            <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 0 0 2.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 0 0 1.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 0 0-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 0 0-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 0 0-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 0 0-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 0 0 1.066-2.573c-.94-1.543.826-3.31 2.37-2.37.997.608 2.296.07 2.572-1.065z" />
              <circle cx="12" cy="12" r="3" />
            </svg>
          </button>
          <span className="level-picker">
            <span
              className="level-picker-label"
              onClick={() => { setLanguageMenuOpen(v => !v); setLevelMenuOpen(false); }}
              title="Switch language"
            >
              {LEVELS[level].torfl}
            </span>
            {languageMenuOpen && (
              <>
                <div className="level-menu-overlay" onClick={() => setLanguageMenuOpen(false)} />
                <div className="level-menu">
                  <button type="button" className="level-menu-item" onClick={onSwitchLanguage}>Chinese (HSK)</button>
                  <button type="button" className="level-menu-item active" onClick={() => setLanguageMenuOpen(false)}>Russian (TORFL)</button>
                </div>
              </>
            )}
          </span>{" "}
          /{" "}
          <span className="level-picker">
            <span
              className="level-picker-label"
              onClick={() => { setLevelMenuOpen(v => !v); setLanguageMenuOpen(false); }}
              title="Switch level"
            >
              {level}
            </span>
            {levelMenuOpen && (
              <div className="level-dropdown">
                {LEVEL_ORDER.map(lv => (
                  <div
                    key={lv}
                    className={`level-option${lv === level ? " level-option-active" : ""}`}
                    onClick={() => selectLevel(lv)}
                  >
                    {LEVELS[lv].cyr} · {lv}
                  </div>
                ))}
              </div>
            )}
          </span>{" "}
          Vocabulary · {totalWords} words
        </div>
        <div className="range-box">
          <div className="range-header">
            <span className="mastery-label">Word Range</span>
            <span className="mastery-count">#{rangeStart + 1} – #{rangeEnd + 1} <span style={{color:"var(--muted-strong)"}}>({rangeEnd - rangeStart + 1} words)</span></span>
          </div>
          <div className="range-row">
            <div className="range-group">
              <label className="range-label">From</label>
              <select className="range-select" value={rangeStart} onChange={e => setRangeStart(Math.min(Number(e.target.value), rangeEnd))}>
                {Array.from({length: totalWords}, (_, i) => (
                  <option key={i} value={i}>#{i + 1} {orderedWords[i].ru}</option>
                ))}
              </select>
            </div>
            <div className="range-group">
              <label className="range-label">To</label>
              <select className="range-select" value={rangeEnd} onChange={e => setRangeEnd(Math.max(Number(e.target.value), rangeStart))}>
                {Array.from({length: totalWords}, (_, i) => (
                  <option key={i} value={i}>#{i + 1} {orderedWords[i].ru}</option>
                ))}
              </select>
            </div>
          </div>
          {(() => {
            const hundredBase = Math.floor(rangeStart / 100) * 100;
            const isFullRange = rangeStart === 0 && rangeEnd === totalWords - 1;
            const relStart = rangeStart - hundredBase;
            const relEnd = rangeEnd - hundredBase;
            const thousandTierCount = Math.ceil(totalWords / 1000);
            const thousandBase = Math.floor(rangeStart / 1000) * 1000;
            const thousandTiers = thousandTierCount > 1
              ? Array.from({length: thousandTierCount}, (_, k) => k * 1000)
              : [];
            const tierStart = thousandBase;
            const tierEnd = Math.min(thousandBase + 999, totalWords - 1);
            const hundredBuckets = (tierEnd - tierStart + 1) > 100
              ? Array.from({length: Math.ceil((tierEnd - tierStart + 1) / 100)}, (_, i) => [tierStart + i * 100, Math.min(tierStart + i * 100 + 99, totalWords - 1)])
              : [];
            const rangePresets = [...hundredBuckets, [0, totalWords - 1]];
            return (
              <div className="range-main">
                <div className="range-left">
                  {thousandTiers.length > 0 && (
                    <div className="range-presets range-presets-thousands">
                      {thousandTiers.map(t => {
                        const tCappedEnd = Math.min(t + 999, totalWords - 1);
                        const isActive = !isFullRange && thousandBase === t;
                        return (
                          <button key={"t" + t} className={`preset-btn preset-btn-thousand${isActive ? " preset-active" : ""}`}
                            onClick={() => { setRangeStart(t); setRangeEnd(tCappedEnd); }}>
                            {t}+
                          </button>
                        );
                      })}
                    </div>
                  )}
                  <div className="range-presets">
                    {rangePresets.map(([s,e]) => {
                      const cappedE = Math.min(e, totalWords - 1);
                      const isAllPreset = s === 0 && cappedE === totalWords - 1;
                      const isActive = isAllPreset
                        ? isFullRange
                        : (!isFullRange && hundredBase === s && rangeStart >= s && rangeEnd <= cappedE);
                      return (
                        <button key={s+"-"+e} className={`preset-btn${isActive ? " preset-active" : ""}`}
                          onClick={() => { setRangeStart(s); setRangeEnd(cappedE); }}>
                          {isAllPreset ? "All" : `${s+1}–${cappedE+1}`}
                        </button>
                      );
                    })}
                  </div>
                </div>
                <div className="subrange-wrap">
                  <span className="subrange-num" style={{visibility: "hidden"}} aria-hidden="true">0</span>
                  <span className="subrange-dot" style={{visibility: "hidden"}} aria-hidden="true" />
                  <div className="subrange-col">
                  {SUBRANGE_MARKS.flatMap((m, i, marks) => {
                    const els = [<span key={`n${m}`} className="subrange-num">{m}</span>];
                    if (i < marks.length - 1) {
                      const subStart = marks[i];
                      const subEnd = marks[i + 1] - 1;
                      const dotActive = relEnd < 100 && relStart >= 0 && subStart >= relStart && subEnd <= relEnd;
                      els.push(
                        <button
                          key={`d${m}`}
                          type="button"
                          data-dot-index={i}
                          className={`subrange-dot${dotActive ? " subrange-dot-active" : ""}`}
                          aria-label={`Select ${subStart + 1}-${subEnd + 1} of current block`}
                          onPointerDown={(e) => {
                            if (e.currentTarget.releasePointerCapture) {
                              try { e.currentTarget.releasePointerCapture(e.pointerId); } catch {}
                            }
                            dragBaseRef.current = hundredBase;
                            setDragAnchorIdx(i);
                            applyBlockRange(hundredBase, i, i);
                          }}
                        />
                      );
                    }
                    return els;
                  })}
                  </div>
                </div>
              </div>
            );
          })()}
          <div className="challenge-row">
            <button
              className={`preset-btn challenge-btn${challengeFilter ? " preset-active" : ""}`}
              onClick={() => { setChallengeFilter(v => !v); setEditingThreshold(false); }}
            >
              Hard ({getChallengingWords(orderedWords.slice(rangeStart, rangeEnd + 1)).length})
            </button>
            <button
              type="button"
              className={`preset-btn shuffle-btn${distributeOrder ? " preset-active" : ""}`}
              onClick={() => setDistributeOrder(v => !v)}
              aria-label="Distribute word order across the list"
              title="Distribute order: spreads ranges across the whole list instead of strict alphabetical order"
            >
              <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="16 3 21 3 21 8" />
                <line x1="4" y1="20" x2="21" y2="3" />
                <polyline points="21 16 21 21 16 21" />
                <line x1="15" y1="15" x2="21" y2="21" />
                <line x1="4" y1="4" x2="9" y2="9" />
              </svg>
            </button>
            {challengeFilter && !editingThreshold && (
              <button className="threshold-chip" onClick={() => setEditingThreshold(true)}>
                Threshold {challengeThreshold}
              </button>
            )}
            {challengeFilter && editingThreshold && (
              <input
                className="threshold-input"
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                autoFocus
                defaultValue={challengeThreshold}
                onBlur={e => { setChallengeThreshold(Math.max(1, Number(e.target.value) || 4)); setEditingThreshold(false); }}
                onKeyDown={e => { if (e.key === "Enter") e.target.blur(); }}
              />
            )}
          </div>
        </div>
        <div className="mastery-box">
          <div className="mastery-header">
            <span className="mastery-label">Overall Mastery</span>
            <span className="mastery-count">{masteredCount} / {totalWords}</span>
          </div>
          <div className="mastery-bar-bg">
            <div className="mastery-bar-fill" style={{ width: `${(masteredCount / totalWords) * 100}%` }} />
          </div>
          <div className="mastery-sub">{seenCount} seen · {totalWords - seenCount} unseen · {currentBadList.length} on bad list</div>
        </div>
        <div className="range-box" style={{marginBottom: 16}}>
          <div className="range-header" style={{marginBottom: 10}}>
            <span className="mastery-label">Round Size</span>
            <span className="mastery-count">{roundSize} words</span>
          </div>
          <div className="range-presets">
            {[10, 20, 50, 100].map(n => (
              <button key={n} className={`preset-btn${roundSize === n ? " preset-active" : ""}`}
                onClick={() => setRoundSize(n)}>{n}</button>
            ))}
          </div>
        </div>
        <div className="mode-grid">
          {MODES.map(m => (
            <button key={m.id} className="mode-btn" onClick={() => startQuiz(m.id)}>
              <div className="mode-label">{m.label}</div>
              <div className="mode-desc">{m.desc}</div>
            </button>
          ))}
        </div>
        {currentBadList.length > 0 && (
          <div style={{ marginTop: 16, width: "100%", maxWidth: 460, display: "flex", gap: 8 }}>
            <button className="btn-red" style={{ flex: 1 }} onClick={() => startBadList("mc")}>🔴 Bad List ({currentBadList.length} words)</button>
            <button className="btn-outline" style={{ fontSize: "0.7rem", padding: "10px 12px" }} onClick={clearBadList}>Clear</button>
          </div>
        )}
      </div>
    </>
  );

  if (done) return (
    <>
      <style>{STYLES}</style>
      <div className="app">
        <div className="done-card">
          <div className="done-pct">{pct}%</div>
          <div className="done-label">{isBadListSession ? "Bad List Round" : "This Round"}</div>
          <div className="done-sub">{score.correct} / {score.total} correct</div>
          <div className="done-btns">
            <button className="btn-gold" onClick={replay}>Replay</button>
            <button className="btn-gold" onClick={() => startQuiz(mode)}>New Round</button>
            {currentBadList.length > 0 && <button className="btn-red" onClick={() => startBadList(mode)}>Bad List ({currentBadList.length})</button>}
            {getChallengingWords(orderedWords.slice(rangeStart, rangeEnd + 1)).length > 0 && (
              <button className="btn-outline challenge-outline" onClick={() => { setChallengeFilter(true); startQuiz(mode); }}>
                Hard ({getChallengingWords(orderedWords.slice(rangeStart, rangeEnd + 1)).length})
              </button>
            )}
            <button className="btn-outline" onClick={() => setMode(null)}>← Home</button>
          </div>
        </div>
      </div>
    </>
  );

  const isRussianPrompt = mode === "ru-to-en";
  const isOnBadList = cur && currentBadList.find(w => w.ru === cur.ru);

  return (
    <>
      <style>{STYLES}</style>
      <div className="app">
        <button className="back-btn" onClick={() => setMode(null)}>← home</button>
        <div className="card">
          <div className="progress-bar"><div className="progress-fill" style={{ width: `${progress}%` }} /></div>
          <div className="score-line">
            {index + 1} / {poolSize} · {score.correct} correct
            {isBadListSession && <span style={{ color: "var(--error)", marginLeft: 8 }}>BAD LIST</span>}
          </div>
          <div className="prompt-label">{mode === "ru-to-en" ? "Russian" : "English"}</div>
          {isRussianPrompt
            ? <div className="prompt-ru">{cur?.ruStressed}</div>
            : (
              <div className="prompt-en">
                {cur?.en}
                {cur?.motionDirection && <MotionDirectionHint direction={cur.motionDirection} />}
              </div>
            )
          }
          {mode === "en-to-ru-stress" && <div className="stress-hint">type stress by CAPITALIZING the stressed vowel, e.g. бОльше</div>}
          {!(mode === "en-to-ru-stress") && <div className="spacer" />}

          {mode === "mc" ? (
            <div className="mc-grid">
              {mcChoices.map((ch, idx) => {
                const isCorrect = ch.ru === pool[index]?.ru;
                let cls = "mc-btn";
                if (result !== null) {
                  if (isCorrect && idx === chosen) cls = "mc-btn mc-chosen-correct";
                  else if (isCorrect) cls = "mc-btn mc-reveal";
                  else if (idx === chosen) cls = "mc-btn mc-chosen-wrong";
                }
                return (
                  <button key={ch.ru} className={cls} disabled={result !== null} onClick={() => checkMC(idx)}>
                    {ch.ruStressed}
                  </button>
                );
              })}
            </div>
          ) : (
            <>
              <input
                className={`input-field${result === "correct" ? " input-correct" : result === "wrong" ? " input-wrong" : ""}`}
                placeholder={mode === "en-to-ru" ? "Type in Russian..." : mode === "en-to-ru-stress" ? "Type with CAPS stress..." : "Type English meaning..."}
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={e => {
                  if (e.key === "Enter" && !result && input.trim()) checkTyped();
                  else if (e.key === "Enter" && result) advance();
                }}
                disabled={!!result}
                autoFocus
              />
              {!result && <button className="submit-btn" disabled={!input.trim()} onClick={checkTyped}>CHECK</button>}
            </>
          )}

          {result && (
            <>
              <ChipStateContext.Provider value={{ expandedId: chipExpandedId, setExpandedId: setChipExpandedId, answerVisible, toggleAnswerVisible, showPos }}>
                <div className={`result-box ${result === "correct" ? "result-correct" : "result-wrong"}`}>
                  <div className="status-chip-row">
                    <div className="result-status">{result === "correct" ? "✓ Correct!" : "✗ Incorrect"}</div>
                    <TopChipRow word={cur} />
                  </div>
                  <div className="result-ans-line">
                    <div className="result-ans">{correctAns}</div>
                    {cur?.adjEndings && mode !== "ru-to-en" && (() => {
                      const short = formatAdjEndings(cur.ruStressed, cur.adjEndings);
                      return short
                        ? <span className="adj-endings"> {short.join(" ")}</span>
                        : <span className="adj-endings">, {cur.adjEndings.join(", ")}</span>;
                    })()}
                    <AspectPairInline word={cur} />
                  </div>
                  <AspectPairPanel word={cur} />
                  <BelowWordDetails word={cur} />
                  <GrammarCard word={cur} inline />
                </div>
              </ChipStateContext.Provider>
              <button className="next-btn" ref={nextBtnRef} onClick={advance}>{index + 1 >= poolSize ? "SEE RESULTS →" : "NEXT →"}</button>
            </>
          )}
        </div>
      </div>
    </>
  );
}
